    // as the page reads the bed (Z2's note of 15:04): depth(X, Y) = depth + slope . (X, Y) + relief (none here)
    const tg = C.tan(bed.slope), slope = [tg * bed.dipX, tg * bed.dipY]; bed.tan = Math.abs(tg);
