      const au = Math.abs(u), re = (au > 0.5 ? au : 0.5) * b.cfL / K.nu, lg = C.log10(re) - 2, cf = 0.075 / (lg * lg) + K.dCf;
      Fx += -0.5 * rho * (cdx * b.Amax + cf * b.wet) * u * au * share;
