      const VX = Rm[0] * lx + Rm[1] * ly + Rm[2] * lz, VY = Rm[3] * lx + Rm[4] * ly + Rm[5] * lz, VZ = Rm[6] * lx + Rm[7] * ly + Rm[8] * lz;
