      const fx = Rm[0] * FXw + Rm[3] * FYw + Rm[6] * FZw, fy = Rm[1] * FXw + Rm[4] * FYw + Rm[7] * FZw, fz = Rm[2] * FXw + Rm[5] * FYw + Rm[8] * FZw;
