    let Vair = 0;
    if (b.air && (a0 > 0 || a1 > 0)) {
      b.air.a = 0.5 * (a0 + a1);
      Vair = airVolume(b, sp, -(b.X[2] + R0[6] * (b.air.p[0] - b.C[0]) + R0[7] * (b.air.p[1] - b.C[1]) + R0[8] * (b.air.p[2] - b.C[2])));
    }
