      const hx = 0.5 * h * nu[3], hy = 0.5 * h * nu[4], hz = 0.5 * h * nu[5], q = b.q;
      let w = q[0] - q[1] * hx - q[2] * hy - q[3] * hz, x = q[0] * hx + q[1] + q[2] * hz - q[3] * hy, y = q[0] * hy - q[1] * hz + q[2] + q[3] * hx, zq = q[0] * hz + q[1] * hy - q[2] * hx + q[3];
