  return { CLOCKS, NYT, CONDUCT, SET, ROCKETS, LAMP, LIGHTS, SHIPS, CQD_POS, WRECK_1912, horizon, settings, attach, step, readouts, valid,
    call, rocket, lamp, etaOf, clockText, tNY, tCarp, tCal };
