    if (x > TIER.A[0] && x < TIER.A[1] && z <= C.deckZ('Boat', x)) return x > TIER.screen ? C.halfBreadth(x, z, ship.hull) : TIER.houseA;
    for (const h of TIER.houses) if (x > h.x0 && x <= h.x1 && z <= C.deckZ('Boat', x) + h.h) return h.hw;
